// ============================================================
// IRONSIGHT — i18n localization pipeline (T2-8 / U6, Task 64, spec §48)
// Locale set = Shell Shockers primary observation (research/phase2_findings.md:59):
// English/French/German/Russian/Spanish/Portuguese/Korean/Chinese/Dutch (9).
// Laws: §48.2 one module (maps.js data-file pattern) · §48.3 {token} templates
// (no concatenation for translatable faces) · §48.4 persistence via settings.lang
// default-merge · §48.5 boot order (setLang before boot lines) · §48.6 system-font
// glyph fallback (no CDN CJK webfont) · §48.7 proper-noun law (wordmark, map names,
// weapon names, cosmetic labels stay EN) · §48.8 lang==='en' === current literals.
// Key domains: ix.* index.html static · s.* settings · m.* menu/results/loadout
// · a.* announces · h.* hud · b.* boot lines · c.* content descs (config data).
// ============================================================

