// ============================================================
// API (spec §48.2)
// ============================================================
export const DICTS = { en, fr, de, ru, es, pt, nl, ko, zh };

let cur = 'en';

export function lang() { return cur; }

export function t(key, params) {
  let s = (DICTS[cur] && DICTS[cur][key] !== undefined) ? DICTS[cur][key]
    : (DICTS.en[key] !== undefined ? DICTS.en[key] : key); // §48.2 fallback law: EN, then key itself
  if (params) s = s.replace(/\{(\w+)\}/g, (m, k) => (params[k] !== undefined ? String(params[k]) : m));
  return s;
}

// content-dict helper for config-data strings (§48.7: names stay EN, descs/reqs translate).
// td('fin', f.id) → t('c.fin.' + id); caller keeps the config value as fallback.
export function td(domain, id, params) { return t('c.' + domain + '.' + id, params); }

export function applyStatic(root) {
  const r = root || document;
  r.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.dataset.i18n); });
}

export function setLang(id) {
  if (!DICTS[id]) return false;
  cur = id;
  if (typeof document !== 'undefined') applyStatic(document); // static faces re-render; dynamic faces read t() at call time (§48.5); non-DOM envs (probe/bun) skip
  try { document.documentElement.lang = id; } catch (e) { /* non-DOM env (probe) */ }
  return true;
}

// EN key inventory accessor (probe §48.9 uses this for the parity law)
export function keys() { return Object.keys(DICTS.en); }

// ============================================================
// §62.4 / §62.5b / §62.6 (v1.54, Task 87) — recovery-increment keys.
// MERGE-BLOCK LAW: additive Object.assign over DICTS — the original per-locale
// dicts above stay untouched (diff-surface = this block only). Every locale
// carries the full key set; §48.2 EN fallback remains the safety net.
// Domains: m.* BP mirror faces · s.* TOUCH controls rows · ob.* onboarding faces
// · ix./cr.* the §62.3 career faces Task 83 deferred to THIS increment
// ("other locales join at the i18n-keys recovery increment" — GAP_LEDGER v1.52).
