    'onb.s3.body.gamepad': '오른쪽 스틱이 카메라를 회전합니다 — 최대 편차 ≈ 178°/s · 감도는 설정 → 조작에 있습니다.',
    'onb.s3.body.touch': '시선 패드를 드래그해 회전하세요 · 속도는 설정 → 조작의 TOUCH 슬라이더를 따릅니다.',
