    'onb.s4.body.gamepad': 'RT로 발사 · LT로 조준 — ADS는 탄착군을 좁히고 보폭을 늦춥니다.',
    'onb.s4.body.touch': 'FIRE 버튼을 길게 눌러 발사 · ADS를 탭해 조준 전환 — 조준은 탄착군을 좁히고 보폭을 늦춥니다.',
