    'onb.s5.body.gamepad': 'X로 재장전 · Y로 빠른 교체. 전투 중 빈 탄창? 빠른 교체가 재장전보다 빠릅니다.',
    'onb.s5.body.touch': '비었으면 RELOAD 탭 · SWAP 탭으로 빠른 교체. 전투 중 빈 탄창? 교체가 재장전보다 빠릅니다.',
    'onb.s5.hint.mouse': '탄창을 비우고 재장전(R), 그다음 빠른 교체(Q) — 전체 비트가 기록되면 단계가 완료됩니다.',
    'onb.s5.hint.gamepad': '탄창을 비우고 재장전(X), 그다음 빠른 교체(Y) — 전체 비트가 기록되면 단계가 완료됩니다.',
    'onb.s5.hint.touch': '탄창을 비우고 RELOAD 탭, 그다음 SWAP 탭 — 전체 비트가 기록되면 단계가 완료됩니다.',
