    'onb.s6.body.mouse': 'G로 파편수류탄 투척 — 길게 눌러 코킹 · 4로 전술 어빌리티 발동. 둘 다 재충전됩니다; 낭비하지 마세요.',
    'onb.s6.body.gamepad': 'RB로 파편수류탄 투척 · LB로 전술 어빌리티 발동. 둘 다 재충전됩니다; 낭비하지 마세요.',
    'onb.s6.body.touch': '수류탄 버튼을 길게 눌러 코킹한 뒤 놓으세요 · 어빌리티 버튼을 탭. 둘 다 재충전됩니다; 낭비하지 마세요.',
    'onb.s6.hint.mouse': '엄폐물 뒤에서 수류탄을 코킹하고 어빌리티를 사용하세요 — 둘 다 발동되면 단계가 완료됩니다.',
    'onb.s6.hint.gamepad': '엄폐물 뒤에서 수류탄을 코킹하고 어빌리티를 사용하세요 — 둘 다 발동되면 단계가 완료됩니다.',
    'onb.s6.hint.touch': '엄폐물 뒤에서 수류탄을 코킹하고 어빌리티를 사용하세요 — 둘 다 발동되면 단계가 완료됩니다.',
    'onb.s7.title.mouse': '목표 + 핑 — Z / 휠 클릭',
    'onb.s7.title.gamepad': '목표 + 핑 — 방향키',
    'onb.s7.title.touch': '목표 + 핑',
    'onb.s7.body.mouse': '목표가 매치를 결정합니다 — 링을 유지하고, 설치하고, 태그를 확인하세요. Z 또는 휠 버튼이 월드에 핑을 찍습니다: 팀은 당신이 보는 것을 봅니다.',
    'onb.s7.body.gamepad': '목표가 매치를 결정합니다 — 링을 유지하고, 설치하고, 태그를 확인하세요. 방향키가 월드에 핑을 찍습니다: 팀은 당신이 보는 것을 봅니다.',
    'onb.s7.body.touch': '목표가 매치를 결정합니다 — 링을 유지하고, 설치하고, 태그를 확인하세요. 핑은 위협을 표시합니다: 팀은 당신이 보는 것을 봅니다.',
    'onb.s7.hint.mouse': '거점을 점령하거나 핑을 찍으세요 — 어느 쪽이든 마지막 보상이 완료됩니다. 그다음 DEPLOY를 누르세요.',
    'onb.s7.hint.gamepad': '거점을 점령하거나 핑을 찍으세요 — 어느 쪽이든 마지막 보상이 완료됩니다. 그다음 DEPLOY를 누르세요.',
