      'onb.body.control': 'Choisissez votre scheme avant le premier déploiement : le tactile reçoit une disposition style CODM avec aide à la visée rotationnelle ; le bureau tourne clavier & souris, et la manette est prise en charge partout. Chaque bind est remappable dans Paramètres → Contrôles.',
      'onb.title.move': 'SE DÉPLACER',
      'onb.body.move': 'Poussez le stick (ou ZQSD) pour avancer — pousser vers l’avant sprinte, et l’auto-sprint tactile est ACTIVÉ. Sautez en sprintant pour glisser, accroupissez-vous pour réduire votre profil, et restez en mouvement : l’immobilité est un arrêt de mort.',
      'onb.title.shoot': 'TIRER',
      'onb.body.shoot': 'Maintenez VISÉE pour stabiliser le réticule, touchez TIR par rafales courtes. Les hitmarkers confirment les touches et les headshots rapportent de l’XP bonus. Tactile : un cône d’aide à la visée de {assist}° aide déjà votre drag.',
      'onb.title.utility': 'GRENADES & TACTIQUES',
      'onb.body.utility': 'Le bouton grenade lance une frag — fusible {fuse}s, cuisable, jusqu’à {dmg} dégâts au centre. Votre capacité tactique (Dash par défaut) part du bouton d’aptitude. Ni l’une ni l’autre ne coûte de munitions : dépensez-les.',
      'onb.title.drill': 'OPTIONNEL : EXERCICE DE 30 SECONDES',
      'onb.body.drill': 'Envie d’un essai à vide ? Le mode Entraînement vous drop contre des bots IA — 30 secondes suffisent pour verrouiller la sensation. Passez si vous préférez apprendre en direct ; l’exercice vous attend dans la liste des modes.',
      'onb.title.sens': 'RÉGLEZ VOTRE VISÉE',
      'onb.body.sens': 'Sensibilité, multiplicateur ADS et options gyro vivent dans Paramètres → Contrôles. Le look tactile tourne à {look}× de sensibilité de drag et se règle séparément de l’ADS. Rien n’est définitif — réglez à tout moment.',
      'onb.title.finish': 'BOOT CAMP TERMINÉ',
      'onb.body.finish': 'Voilà tout le tutoriel — environ {min} minutes, style Apex. Chaque étape était passable, mais finir paie : +{xp} XP de pass et +{cr} CR tombent dans votre compte maintenant. Modes, passes et récompenses continuent de se débloquer en jouant.',
      'm7.fireMode': 'MODE DE TIR',
      'm18.slotprimary': 'PRINCIPALE',
      'm18.slotsecondary': 'SECONDAIRE',
      'm18.stock': 'D’ORIGINE',
      'ix.online': 'EN LIGNE', 'ix.onlineHint': 'jouer avec d’autres', 'ix.pgOnline': 'EN LIGNE',
      'on.quick': 'PARTIE RAPIDE', 'on.quickWait': 'Recherche du lobby le plus peuplé…',
      'on.rank': 'REJOINDRE LA FILE CLASSÉE', 'on.rankWait': 'File classée : triée par palier RP — s’élargit en attendant…',
      'on.create': 'CRÉER UN SALON PRIVÉ', 'on.or': 'ou rejoindre par code', 'on.join': 'REJOINDRE', 'on.codePh': 'CODE',
      'on.offline': 'Service de salon hors ligne — la partie rapide et la file classée se connectent dès qu’une session est active ; les salons privés fonctionnent via lien d’invitation.',
      'm8.mapExpand': 'AGRANDIR LA CARTE',
      'm8.mapClose': 'FERMER LA CARTE',
