      'onb.paid': 'BEZAHLT +{xp} Pass-XP · +{cr} CR',
      'onb.entryBtn': 'WIEDERHOLEN',
      'onb.rewardChip': '+{xp} Pass-XP · +{cr} CR',
      'onb.entry': 'TUTORIAL WIEDERHOLEN',
      'onb.title.control': 'WÄHLE DEINE STEUERUNG',
      'onb.body.control': 'Wähle dein Schema vor dem ersten Abwurf: Touch bekommt ein CODM-artiges Layout mit rotierender Zielhilfe; Desktop läuft mit Tastatur & Maus, Gamepad wird überall unterstützt. Jede Belegung ist später unter Einstellungen → Steuerung umbindbar.',
      'onb.title.move': 'BEWEGEN',
      'onb.body.move': 'Stick (oder WASD) drücken zum Bewegen — nach vorne sprintet, und Touch-Autosprint ist AN. Sprintend springen zum Rutschen, ducken für kleinere Silhouette, und bleib in Bewegung: Stillstand ist ein Todesurteil.',
      'onb.title.shoot': 'FEUERN',
      'onb.body.shoot': 'ZIELEN halten zum Stabilisieren, FEUER in kurzen Stößen tippen. Hitmarker bestätigen Treffer, Kopfschüsse zahlen Bonus-XP. Touch: ein {assist}°-Zielhilfekegel unterstützt deinen Drag bereits.',
      'onb.title.utility': 'GRANATEN & TAKTIK',
      'onb.body.utility': 'Der Granatenknopf wirft eine Frag — {fuse}s Zünder, kochbar, bis zu {dmg} Schaden im Zentrum. Deine taktische Fähigkeit (standardmäßig Dash) zündet über den Fähigkeitenknopf. Beide kosten keine Munition — setz sie ein.',
      'onb.title.drill': 'OPTIONAL: 30-SEKUNDEN-DRILL',
      'onb.body.drill': 'Erst eine Trockenübung? Der Übungsmodus lässt dich gegen KI-Bots abwerfen — 30 Sekunden genügen, um das Gefühl zu verankern. Überspring, wenn du live lernen willst; der Drill wartet in der Modusliste.',
      'onb.title.sens': 'STIMME DEIN ZIEL AB',
      'onb.body.sens': 'Empfindlichkeit, ADS-Multiplikator und Gyro-Optionen liegen unter Einstellungen → Steuerung. Touch-Look läuft mit {look}× Drag-Empfindlichkeit und wird getrennt von ADS abgestimmt. Nichts ist endgültig — jederzeit nachjustieren.',
      'onb.title.finish': 'BOOT CAMP ABGESCHLOSSEN',
      'onb.body.finish': 'Das war das ganze Tutorial — etwa {min} Minuten, Apex-Stil. Jede Stufe war überspringbar, aber Abschluss zahlt: +{xp} Pass-XP und +{cr} CR landen jetzt auf deinem Konto. Modi, Pässe und Rewards schalten beim Spielen weiter frei.',
      'm7.fireMode': 'FEUERMODUS',
      'm18.slotprimary': 'PRIMÄR',
      'm18.slotsecondary': 'SEKUNDÄR',
      'm18.stock': 'SERIENMÄSSIG',
