      'onb.entry': 'ПРОЙТИ ОБУЧЕНИЕ СНОВА',
      'onb.title.control': 'ВЫБЕРИТЕ УПРАВЛЕНИЕ',
      'onb.body.control': 'Выберите схему до первого десанта: сенсорные игроки получают раскладку в стиле CODM с поворотным помощником прицеливания; на ПК — клавиатура и мышь, геймпад поддержан везде. Каждая привязка переназначается в Настройки → Управление.',
      'onb.title.move': 'ДВИЖЕНИЕ',
      'onb.body.move': 'Толкайте стик (или WASD) для движения — вперёд означает спринт, автоспринт на сенсорном включён. Прыжок в спринте — подкат, приседание уменьшает силуэт, и не стойте на месте: неподвижность — смертный приговор.',
      'onb.title.shoot': 'СТРЕЛЬБА',
      'onb.body.shoot': 'Держите ПРИЦЕЛ для стабилизации, нажимайте ОГОНЬ короткими сериями. Хитмаркеры подтверждают попадания, хедшоты дают бонусный XP. Сенсорным игрокам: конус помощи прицеливания {assist}° уже помогает вашему доводу.',
      'onb.title.utility': 'ГРАНАТЫ И ТАКТИКА',
      'onb.body.utility': 'Кнопка гранаты бросает фраг — запал {fuse}s, можно приготовить, до {dmg} урона в центре. Тактическая способность (по умолчанию Рывок) запускается кнопкой способности. Обе не тратят патроны — тратьте смело.',
      'onb.title.drill': 'ОПЦИЯ: 30-СЕКУНДНЫЙ ТРЕНАЖ',
      'onb.body.drill': 'Хотите сначала потренироваться? Режим практики высаживает вас против ИИ-ботов — 30 секунд хватит, чтобы закрепить ощущение. Пропустите, если лучше учитесь в бою; тренаж ждёт в списке режимов.',
      'onb.title.sens': 'НАСТРОЙТЕ ПРИЦЕЛ',
      'onb.body.sens': 'Чувствительность, множитель ADS и опции гироскопа живут в Настройки → Управление. Сенсорный обзор работает на {look}× чувствительности довода и настраивается отдельно от ADS. Ничего не окончательно — перенастройте в любой момент.',
      'onb.title.finish': 'УЧЕБНЫЙ ЛАГЕРЬ ПРОЙДЕН',
      'onb.body.finish': 'Это весь туториал — около {min} минут, в стиле Apex. Каждый этап можно было пропустить, но завершение платит: +{xp} XP пасса и +{cr} CR зачислены на ваш счёт. Режимы, пассы и награды продолжают открываться по мере игры.',
      'm7.fireMode': 'РЕЖИМ ОГНЯ',
      'm18.slotprimary': 'ОСНОВНОЕ',
      'm18.slotsecondary': 'ВТОРИЧНОЕ',
