      'onb.title.control': 'ELIGE TUS CONTROLES',
      'onb.body.control': 'Elige tu esquema antes del primer despliegue: los jugadores táctiles reciben una disposición estilo CODM con asistencia de puntería rotacional; escritorio usa teclado y ratón, y el mando está soportado en todas partes. Cada vinculación se remapea después en Ajustes → Controles.',
      'onb.title.move': 'MUÉVETE',
      'onb.body.move': 'Empuja el stick (o WASD) para moverte — empujar hacia adelante es sprint, y el auto-sprint táctil está ACTIVADO. Salta corriendo para deslizarte, agáchate para reducir tu perfil, y sigue moviéndote: quedarte quieto es sentencia de muerte.',
      'onb.title.shoot': 'DISPARA',
      'onb.body.shoot': 'Mantén APUNTAR para estabilizar la mira, toca DISPARAR en ráfagas cortas. Los hitmarkers confirman impactos y los tiros a la cabeza pagan XP extra. Táctil: un cono de asistencia de puntería de {assist}° ya está ayudando tu arrastre.',
      'onb.title.utility': 'GRANADAS Y TÁCTICAS',
      'onb.body.utility': 'El botón de granada lanza una frag — espoleta de {fuse}s, cocinable, hasta {dmg} de daño en el centro. Tu habilidad táctica (Dash por defecto) se lanza desde el botón de habilidad. Ninguna gasta munición: úsalas.',
      'onb.title.drill': 'OPCIONAL: EJERCICIO DE 30 SEGUNDOS',
      'onb.body.drill': '¿Quieres un ensayo primero? El modo práctica te despliega contra bots de IA — 30 segundos bastan para fijar la sensación. Omítelo si prefieres aprender en vivo; el ejercicio espera en la lista de modos.',
      'onb.title.sens': 'AJUSTA TU PUNTERÍA',
      'onb.body.sens': 'La sensibilidad, el multiplicador ADS y las opciones de giroscopio viven en Ajustes → Controles. La vista táctil corre a {look}× de sensibilidad de arrastre y se ajusta aparte del ADS. Nada es final — reajusta cuando quieras.',
      'onb.title.finish': 'CAMPO DE ENTRENAMIENTO COMPLETADO',
      'onb.body.finish': 'Ese es todo el tutorial — unos {min} minutos, estilo Apex. Cada etapa era omisible, pero terminar paga: +{xp} XP de pase y +{cr} CR llegan a tu cuenta ahora. Los modos, pases y recompensas siguen desbloqueándose al jugar.',
