      'onb.title.control': 'ESCOLHE TUS CONTROLOS',
      'onb.body.control': 'Escolhe o teu esquema antes da primeira queda: jogadores de toque recebem uma disposição estilo CODM com assistência de mira rotacional; desktop corre teclado & rato, e gamepad é suportado em todo o lado. Cada bind é remapeável depois em Definições → Controlos.',
