      'onb.body.move': 'Empurra o stick (ou WASD) para te moveres — empurrar para a frente sprinta, e o auto-sprint de toque está LIGADO. Salta em sprint para deslizar, agacha para reduzir o perfil, e continua em movimento: ficar parado é sentença de morte.',
