      'onb.title.control': 'KIES JE BESTURING',
      'onb.body.control': 'Kies je schema vóór de eerste drop: touch-spelers krijgen een CODM-stijl indeling met roterende mikhelper; desktop draait toetsenbord & muis, en gamepad wordt overal ondersteund. Elke bind is later hermapbaar in Instellingen → Besturing.',
      'onb.title.move': 'BEWEEG',
      'onb.body.move': 'Duw de stick (of WASD) om te bewegen — naar voren sprint, en touch-auto-sprint staat AAN. Sprintend springen om te glijden, duck voor een kleiner profiel, en blijf bewegen: stilstand is een doodsvonnis.',
      'onb.title.shoot': 'SCHIET',
      'onb.body.shoot': 'Houd RICHT voor een stabiel reticle, tik SCHIET in korte bursts. Hitmarkers bevestigen treffers en headshots betalen bonus-XP. Touch: een {assist}°-mikhulpconus helpt je drag al.',
      'onb.title.utility': 'GRANATEN & TACTICS',
      'onb.body.utility': 'De granaatknop gooit een frag — {fuse}s lont, kookbaar, tot {dmg} schade in het midden. Je tactische vaardigheid (standaard Dash) vuurt vanaf de vaardigheidsknop. Allebei kosten geen munitie — zet ze in.',
      'onb.title.drill': 'OPTIONEEL: 30-SECONDEN DRILL',
      'onb.body.drill': 'Eerst een droge oefening? De oefenmodus dropt je tegen AI-bots — 30 seconden is genoeg om het gevoel vast te zetten. Sla over als je liever live leert; de drill wacht in de moduslijst.',
      'onb.title.sens': 'STEM JE MIK AF',
      'onb.body.sens': 'Gevoeligheid, de ADS-vermenigvuldiger en gyro-opties staan in Instellingen → Besturing. Touch-look draait op {look}× drag-gevoeligheid en wordt apart van ADS afgestemd. Niets is definitief — stem op elk moment bij.',
      'onb.title.finish': 'BOOT CAMP VOLTOOID',
      'onb.body.finish': 'Dat was de hele tutorial — zo’n {min} minuten, Apex-stijl. Elke stap was overslaanbaar, maar voltooien betaalt: +{xp} Pas-XP en +{cr} CR landen nu op je account. Modi, passes en rewards blijven ontgrendelen terwijl je speelt.',
