      'onb.aria': '튜토리얼',
      'onb.step': '단계 {n} / {total}',
      'onb.paid': '지급 완료 +{xp} 패스 XP · +{cr} CR',
      'onb.entryBtn': '다시 하기',
      'onb.rewardChip': '+{xp} 패스 XP · +{cr} CR',
      'onb.entry': '튜토리얼 다시 플레이',
      'onb.title.control': '조작법을 선택하세요',
      'onb.body.control': '첫 강하 전에 조작 스킴을 선택하세요: 터치 플레이어는 회전형 조준 보조가 켜진 CODM 스타일 레이아웃을, 데스크톱은 키보드 & 마우스를, 게임패드는 어디서든 지원합니다. 모든 바인딩은 설정 → 조작에서 나중에 다시 매핑할 수 있습니다.',
      'onb.title.move': '이동',
      'onb.body.move': '스틱(또는 WASD)을 밀어 이동하세요 — 앞으로 밀면 전력 질주이며 터치 자동 질주가 켜져 있습니다. 질주 중 점프로 슬라이드하고, 웅크려 표적을 줄이고, 계속 움직이세요. 멈춰 서면 사형 선고입니다.',
      'onb.title.shoot': '사격',
      'onb.body.shoot': '조준을 길게 눌러 조준경을 고정하고, FIRE를 짧은 점사로 탭하세요. 히트마커가 명중을 확인하고 헤드샷은 보너스 XP를 줍니다. 터치 플레이어: {assist}° 조준 보조 원뿔이 이미 드래그를 도와줍니다.',
      'onb.title.utility': '수류탄 & 전술',
      'onb.body.utility': '수류탄 버튼은 프래그를 던집니다 — {fuse}초 신관, 조리 가능, 중심에서 최대 {dmg} 피해. 전술 능력(기본 대시)은 능력 버튼에서 발동합니다. 둘 다 탄약을 소모하지 않으니 아껴두지 마세요.',
      'onb.title.drill': '선택: 30초 훈련',
      'onb.body.drill': '먼저 연습할까요? 연습 모드에서 AI 봇과 대결합니다 — 30초면 감각을 익히기 충분합니다. 실전에서 배우고 싶으면 건너뛰세요. 훈련은 모드 목록에서 기다립니다.',
      'onb.title.sens': '조준을 조율하세요',
      'onb.body.sens': '감도, ADS 배율, 자이로 옵션은 설정 → 조작에 있습니다. 터치 시야는 {look}× 드래그 감도로 작동하며 ADS와 별도로 조율됩니다. 아무것도 최종이 아닙니다 — 언제든 다시 조율하세요.',
      'onb.title.finish': '부트캠프 완료',
      'onb.body.finish': '이것으로 튜토리얼 전부입니다 — 약 {min}분, Apex 스타일. 모든 단계를 건너뛸 수 있었지만 완료하면 보상이 있습니다: +{xp} 패스 XP와 +{cr} CR이 지금 계정에 들어갑니다. 모드, 패스, 보상은 플레이하며 계속 해금됩니다.',
      'm7.fireMode': '발사 모드',
