      'on.quick': '빠른 대전', 'on.quickWait': '가장 활발한 공개 로비를 찾는 중…',
      'on.rank': '랭크 대기열 참가', 'on.rankWait': '랭크 대기열: RP 등급별 분류 — 기다릴수록 폭이 넓어집니다…',
      'on.create': '비공개 방 만들기', 'on.or': '또는 코드로 참가', 'on.join': '참가', 'on.codePh': '코드',
